    public sealed class ApiMember
    {
        public ApiMember(string name, string kind, string type, string parameters)
        {
            Name = name; Kind = kind; Type = type; Parameters = parameters;
        }
        public string Name { get; }
        public string Kind { get; }
        public string Type { get; }
        public string Parameters { get; }
        public override string ToString() => Kind == "Property" ? $"{Type} {Name}" : $"{Type} {Name}({Parameters})";
    }

    public sealed class FeatureApiDescriptor
    {
        public FeatureApiDescriptor(string interfaceName, string mfcClass, uint typeId, string modelTypeName, IReadOnlyList<ApiMember> members)
